insert into public.stock_movements (
  master_batch_id, product_id, branch_id, movement_type, base_uom,
  base_qty_delta, balance_after, unit_cost_cents, reason
)
select i.id, i.product_id, i.branch_id, 'INTAKE', p.base_uom,
       i.remaining_base_qty, i.remaining_base_qty, i.cost_per_base_unit_cents,
       'Opening stock'
  from inserted i
  join public.products p on p.id = i.product_id
 where i.remaining_base_qty > 0;

-- The three flower grades: file the opening flower under Indoor so the POS
-- category filter has something to show. Re-file products from the inventory
-- screen.
update public.products
   set category_id = (select id from public.catalogue_categories where name = 'Indoor')
 where category = 'FLOWER' and category_id is null;
